const accountUpdate = z.object({ status:z.enum(["pending","active","suspended","closed"]), creditLimit:z.number().int().min(0), paymentTermsDays:z.number().int().min(0).max(120), billingFrequency:z.enum(["manual","weekly","monthly"]).default("manual"), autoChargeStatements:z.boolean().default(false), periodSpendLimit:z.number().int().positive().nullable().default(null), periodSpendFrequency:z.enum(["weekly","monthly"]).default("monthly"), organizationPin:z.union([pinSchema,z.literal("")]).optional().default("") });
const houseOrderSchema = z.object({ accountId:z.uuid(), idempotencyKey:z.string().min(8).max(80), locationId:z.string(), fulfillment:z.record(z.string(),z.unknown()), lineItems:z.array(z.object({ catalog_object_id:z.string(), quantity:z.string(), modifiers:z.array(z.object({ catalog_object_id:z.string() })).optional() })).min(1) });
const applicationSchema=z.object({tenantSlug:z.string().min(2).default("amazing-donuts"),organizationName:z.string().trim().min(2).max(160),organizationType:z.string().trim().min(2).max(80),contactName:z.string().trim().min(2).max(120),email:z.string().email(),phone:z.string().trim().max(40).refine(value=>!value||isValidNorthAmericanPhone(value),"Enter a valid Canadian or US phone number.").optional().default(""),headCount:z.string().trim().max(40).optional().default(""),neededFor:z.iso.date(),fulfillment:z.string().trim().min(2).max(40),products:z.array(z.string().trim().min(1).max(80)).min(1).max(20),notes:z.string().trim().max(3000).optional().default(""),website:z.string().max(0).optional().default("")});
const houseApplicationSchema=z.object({organizationName:z.string().trim().min(2).max(160),organizationType:z.string().trim().min(2).max(80),phone:z.string().trim().max(40).refine(value=>!value||isValidNorthAmericanPhone(value),"Enter a valid Canadian or US phone number.").optional().default(""),requestedCreditLimit:z.coerce.number().min(0).max(1000000),estimatedOrderTotal:z.coerce.number().min(0).max(1000000).default(0),billingFrequency:z.enum(["weekly","monthly"]),invoiceEmail:z.string().email(),organizationPin:pinSchema,address:z.object({addressLine1:z.string().trim().min(2).max(180),addressLine2:z.string().trim().max(180).optional().default(""),locality:z.string().trim().min(2).max(100),administrativeDistrictLevel1:z.string().trim().min(2).max(80),postalCode:z.string().trim().min(3).max(20),country:z.string().trim().length(2).default("CA")}),authorizedPurchasers:z.array(z.object({name:z.string().trim().min(2).max(120),email:z.string().email(),organizationRole:z.string().trim().min(2).max(80),pin:pinSchema})).max(25).default([]),notes:z.string().trim().max(3000).optional().default("")});
const applicationReviewSchema=z.object({status:z.enum(["approved","rejected"]),reviewNotes:z.string().trim().max(2000).optional().default(""),creditLimit:z.number().int().min(0).max(100000000).default(0),paymentTermsDays:z.number().int().min(0).max(120).default(30)});
const bulkReviewSchema=z.object({status:z.enum(["approved","rejected"]),reviewNotes:z.string().trim().max(2000).optional().default("")});
const registerSchema=z.object({tenantSlug:z.string().min(2).default("amazing-donuts"),firstName:z.string().trim().min(1).max(80),lastName:z.string().trim().min(1).max(80),email:z.string().email(),phone:z.string().trim().max(40).refine(value=>!value||isValidNorthAmericanPhone(value),"Enter a valid Canadian or US phone number.").optional().default(""),password:z.string().min(8).max(200)});
const cartSchema=z.array(z.object({name:z.string().trim().min(1).max(180),quantity:z.number().int().min(1).max(99)})).min(1).max(60);
const fulfillmentSchema=z.object({type:z.enum(["pickup","delivery"]),scheduledAt:z.iso.datetime(),recipient:z.object({displayName:z.string().trim().min(2).max(120),email:z.string().email(),phone:z.string().trim().min(7).max(40).refine(value=>isValidNorthAmericanPhone(value),"Enter a valid Canadian or US phone number.")}),address:z.object({addressLine1:z.string().trim().min(2).max(180),addressLine2:z.string().trim().max(180).optional().default(""),locality:z.string().trim().min(2).max(100),administrativeDistrictLevel1:z.string().trim().min(2).max(80).default("ON"),postalCode:z.string().trim().min(3).max(20),country:z.string().trim().length(2).default("CA")}).optional(),deliveryInstructions:z.string().trim().max(500).optional().default(""),noContact:z.boolean().optional().default(false)}).superRefine((value,context)=>{if(value.type==="delivery"&&!value.address)context.addIssue({code:"custom",path:["address"],message:"A delivery address is required."});});
const artworkSchema=z.object({assetId:z.uuid(),count:z.number().int().min(1).max(99)});
