async function provisionApplicationMember(pool,tenantSquare,tenantId,account,person){
  const email=String(person.email).toLowerCase(),name=String(person.name).trim(),parts=name.split(/\s+/),firstName=parts.shift()||"Authorized",lastName=parts.join(" ")||"Purchaser";
  let member=(await pool.query("SELECT id FROM users WHERE lower(email)=lower($1)",[email])).rows[0];
  if(!member){
    const found=await tenantSquare.searchCustomers({query:{filter:{email_address:{exact:email}}},limit:1}),customer=found.customers?.[0]||((await tenantSquare.createCustomer({idempotency_key:randomUUID(),given_name:firstName,family_name:lastName,email_address:email})).customer);
    member=await transaction(pool,async client=>{const created=(await client.query("INSERT INTO users(email,password_hash,first_name,last_name,status) VALUES($1,NULL,$2,$3,'active') RETURNING id",[email,firstName,lastName])).rows[0];await client.query("INSERT INTO tenant_memberships(tenant_id,user_id,role,status) VALUES($1,$2,'viewer','active') ON CONFLICT(tenant_id,user_id) DO UPDATE SET status='active'",[tenantId,created.id]);await client.query("INSERT INTO customer_profiles(tenant_id,user_id,square_customer_id) VALUES($1,$2,$3) ON CONFLICT(tenant_id,user_id) DO NOTHING",[tenantId,created.id,customer.id]);return created;});
  }
  await pool.query(`INSERT INTO account_users(account_id,user_id,role,organization_role,purchaser_pin_hash) VALUES($1,$2,'purchaser',$3,$4) ON CONFLICT(account_id,user_id) DO UPDATE SET role=CASE WHEN account_users.role='account_admin' THEN account_users.role ELSE 'purchaser' END,organization_role=CASE WHEN account_users.role='account_admin' THEN account_users.organization_role ELSE EXCLUDED.organization_role END,purchaser_pin_hash=EXCLUDED.purchaser_pin_hash,status='active'`,[account.id,member.id,normalizeOrganizationRole(person.organizationRole),person.pinHash]);
}

async function updateOrganizationSettings(pool,tenantSquare,account,input){
  const phone=normalizeNorthAmericanPhone(input.phone),metadata={...(account.metadata||{}),organizationType:input.organizationType,phone,address:input.address};
  if(input.organizationPin)await syncInstitutionalPinNote(tenantSquare,account.square_customer_id,input.organizationPin);
  if(account.square_customer_id)await tenantSquare.updateCustomer(account.square_customer_id,{company_name:input.organizationName,email_address:input.billingEmail,phone_number:phone||undefined,address:input.address.addressLine1?squareAddress(input.address):undefined});
  return transaction(pool,async client=>{const updated=(await client.query("UPDATE accounts SET organization_name=$2,billing_contact=$3,billing_email=lower($4),metadata=$5,updated_at=now() WHERE id=$1 RETURNING *",[account.id,input.organizationName,input.billingContact,input.billingEmail,JSON.stringify(metadata)])).rows[0];if(input.organizationPin)await client.query("UPDATE accounts SET account_code_hash=$2,updated_at=now() WHERE id=$1",[account.id,await hashPassword(input.organizationPin)]);return updated;});
}

async function addAccountMember(pool,tenantSquare,account,input){
  const type=organizationRoles[input.organizationType]?input.organizationType:"Other business";
  if(!organizationRoles[type].includes(input.organizationRole))throw Object.assign(new Error("Choose a role that belongs to this organization type."),{status:400,code:"INVALID_ORGANIZATION_ROLE"});
  const found=await pool.query("SELECT u.id,cp.square_customer_id FROM users u LEFT JOIN customer_profiles cp ON cp.user_id=u.id AND cp.tenant_id=$2 WHERE lower(u.email)=lower($1)",[input.email,account.tenant_id]);
  if(!found.rowCount)throw Object.assign(new Error("The member must create a website account before they can be added."),{status:409,code:"MEMBER_ACCOUNT_REQUIRED"});
  await syncInstitutionalPinNote(tenantSquare,found.rows[0].square_customer_id,input.pin);
  const pinHash=await hashPassword(input.pin);
  await transaction(pool,async client=>{await client.query("UPDATE accounts SET metadata=jsonb_set(COALESCE(metadata,'{}'::jsonb),'{organizationType}',to_jsonb($2::text),true),updated_at=now() WHERE id=$1",[account.id,type]);await client.query(`INSERT INTO account_users(account_id,user_id,role,organization_role,purchase_limit,purchaser_pin_hash) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(account_id,user_id) DO UPDATE SET role=EXCLUDED.role,organization_role=EXCLUDED.organization_role,purchase_limit=EXCLUDED.purchase_limit,purchaser_pin_hash=EXCLUDED.purchaser_pin_hash,status='active'`,[account.id,found.rows[0].id,input.role,input.organizationRole,input.purchaseLimit,pinHash]);});
  return {...account,metadata:{...(account.metadata||{}),organizationType:type}};
}

async function syncPurchaserPinByEmail(pool,tenantSquare,tenantId,person){
  const email=String(person.email).toLowerCase(),profile=(await pool.query("SELECT cp.square_customer_id FROM users u JOIN customer_profiles cp ON cp.user_id=u.id AND cp.tenant_id=$1 WHERE lower(u.email)=lower($2) LIMIT 1",[tenantId,email])).rows[0];
  if(profile?.square_customer_id)return syncInstitutionalPinNote(tenantSquare,profile.square_customer_id,person.pin);
  const found=await tenantSquare.searchCustomers({query:{filter:{email_address:{exact:email}}},limit:1});
  if(found.customers?.[0])return syncInstitutionalPinNote(tenantSquare,found.customers[0].id,person.pin);
  const parts=String(person.name).trim().split(/\s+/),firstName=parts.shift()||"Authorized",lastName=parts.join(" ")||"Purchaser";
  await tenantSquare.createCustomer({idempotency_key:randomUUID(),given_name:firstName,family_name:lastName,email_address:email,note:`Institutional authorization PIN: ${person.pin}`});
}

async function hydrateAccount(pool,account) {
  const [credit,orders,ledger,statements,payments,purchasers,cards]=await Promise.all([accountCredit(pool,account.id),pool.query(`SELECT o.*,u.first_name AS purchaser_first_name,u.last_name AS purchaser_last_name,u.email AS purchaser_email,COALESCE(pa.paid_amount,0)::bigint AS paid_amount,GREATEST(0,o.total-COALESCE(pa.paid_amount,0))::bigint AS balance_due FROM orders o LEFT JOIN users u ON u.id=o.purchaser_user_id LEFT JOIN (SELECT order_id,SUM(amount)::bigint AS paid_amount FROM payment_allocations WHERE status='completed' AND order_id IS NOT NULL GROUP BY order_id) pa ON pa.order_id=o.id WHERE o.account_id=$1 ORDER BY o.ordered_at DESC LIMIT 50`,[account.id]),pool.query(`SELECT jt.id,jt.transaction_type,jt.description,jt.effective_at,jp.amount,jp.currency,u.first_name AS purchaser_first_name,u.last_name AS purchaser_last_name,u.email AS purchaser_email FROM journal_transactions jt JOIN journal_postings jp ON jp.transaction_id=jt.id LEFT JOIN users u ON u.id=jt.created_by WHERE jt.account_id=$1 AND jp.ledger_account='accounts_receivable' ORDER BY jt.effective_at DESC LIMIT 100`,[account.id]),pool.query("SELECT s.id,s.statement_number,s.period_start,s.period_end,s.due_at,s.closing_balance,s.currency,s.status,s.payment_token,s.scheduled_charge_at,s.paid_at,COALESCE(pa.paid_amount,0)::bigint AS paid_amount,GREATEST(0,s.closing_balance-COALESCE(pa.paid_amount,0))::bigint AS balance_due FROM statements s LEFT JOIN (SELECT statement_id,SUM(amount)::bigint AS paid_amount FROM payment_allocations WHERE status='completed' GROUP BY statement_id) pa ON pa.statement_id=s.id WHERE s.account_id=$1 ORDER BY s.period_end DESC LIMIT 30",[account.id]),pool.query("SELECT * FROM payment_allocations WHERE account_id=$1 ORDER BY created_at DESC LIMIT 30",[account.id]),pool.query(`SELECT u.id,u.first_name,u.last_name,u.email,u.phone,au.role,au.organization_role,au.purchase_limit,au.status,(au.purchaser_pin_hash IS NOT NULL) AS has_pin FROM account_users au JOIN users u ON u.id=au.user_id WHERE au.account_id=$1 ORDER BY u.last_name,u.first_name`,[account.id]),pool.query("SELECT id,card_brand,last_4,exp_month,exp_year,status FROM account_cards WHERE account_id=$1 ORDER BY created_at DESC",[account.id])]);
  const submittedNames=new Map((account.metadata?.authorizedPurchasers||[]).map(person=>[String(person.email).toLowerCase(),String(person.name).trim()]));
  return {...account,credit,orders:orders.rows,ledger:ledger.rows,statements:statements.rows,payments:payments.rows,purchasers:purchasers.rows.map(person=>({...person,display_name:submittedNames.get(String(person.email).toLowerCase())||`${person.first_name} ${person.last_name}`.trim()})),cards:cards.rows,has_organization_pin:Boolean(account.account_code_hash)};
}

function publicHouseApplication(row){const {organization_pin_hash:_,authorized_purchasers,...application}=row;return {...application,authorized_purchasers:(authorized_purchasers||[]).map(({pinHash:__,...person})=>({...person,hasPin:Boolean(__)})),has_organization_pin:Boolean(row.organization_pin_hash)};}
function normalizeOrganizationRole(value){return String(value||"staff").trim().toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"").slice(0,40)||"staff";}

export async function assertHouseAuthorization({inputPin,purchaserPinHash,accountPinHash,total,purchaseLimit,periodSpendLimit,periodSpent=0,periodFrequency="monthly"}){
  if(!inputPin||!(await verifyPassword(inputPin,purchaserPinHash||accountPinHash)))throw Object.assign(new Error("The authorization PIN is incorrect."),{status:403,code:"INVALID_AUTHORIZATION_PIN"});
  if(purchaseLimit!=null&&Number(total)>Number(purchaseLimit))throw Object.assign(new Error("This order exceeds your purchaser limit."),{status:403,code:"PURCHASER_LIMIT_EXCEEDED"});
  if(periodSpendLimit!=null&&Number(periodSpent)+Number(total)>Number(periodSpendLimit))throw Object.assign(new Error(`This order exceeds the account's ${periodFrequency} spending limit.`),{status:403,code:"PERIOD_SPEND_LIMIT_EXCEEDED"});
}

async function issueStatement(pool,user,accountId,input) {
  const account=await pool.query("SELECT * FROM accounts WHERE id=$1 AND tenant_id=$2",[accountId,user.tenant_id]); if(!account.rowCount) throw Object.assign(new Error("Account not found."),{status:404});
  const [opening,entries]=await Promise.all([pool.query(`SELECT COALESCE(SUM(jp.amount),0)::bigint AS total FROM journal_postings jp JOIN journal_transactions jt ON jt.id=jp.transaction_id WHERE jp.account_id=$1 AND jp.ledger_account='accounts_receivable' AND jt.effective_at<$2::date`,[accountId,input.periodStart]),pool.query(`SELECT jt.id,jt.transaction_type,jt.description,jt.effective_at,jt.source_id,jp.amount,jp.currency,o.line_items,o.tax,o.receipt_number FROM journal_transactions jt JOIN journal_postings jp ON jp.transaction_id=jt.id LEFT JOIN orders o ON o.square_order_id=jt.source_id AND o.account_id=jt.account_id WHERE jp.account_id=$1 AND jp.ledger_account='accounts_receivable' AND jt.effective_at>=$2::date AND jt.effective_at<($3::date+1) ORDER BY jt.effective_at,jt.created_at`,[accountId,input.periodStart,input.periodEnd])]);
  const openingBalance=Number(opening.rows[0].total),charges=entries.rows.filter(e=>Number(e.amount)>0).reduce((s,e)=>s+Number(e.amount),0),credits=entries.rows.filter(e=>Number(e.amount)<0).reduce((s,e)=>s+Math.abs(Number(e.amount)),0),closing=openingBalance+charges-credits;
  const statementNumber=`${account.rows[0].account_code_hint||"HA"}-${input.periodEnd.replaceAll("-","")}-${randomUUID().slice(0,4).toUpperCase()}`;
  const snapshot={organizationName:account.rows[0].organization_name,billingContact:account.rows[0].billing_contact,entries:entries.rows.map(e=>{const itemLines=e.line_items?.map(i=>({name:`${i.name||i.catalog_object_id} x ${i.quantity}`,amount:Number(i.total_money?.amount||Number(i.base_price_money?.amount||0)*Number(i.quantity))}))||[];return {effectiveAt:e.effective_at,description:e.description,amount:Number(e.amount),currency:e.currency,reference:e.receipt_number||e.source_id,lines:itemLines.length?[...itemLines,...(Number(e.tax)?[{name:"Taxes & Fees",amount:Number(e.tax)}]:[]),{name:"Total",amount:Number(e.amount)}]:undefined};})};
  const currency=account.rows[0].currency||entries.rows.find(entry=>entry.currency)?.currency||"CAD";
  const token=randomBytes(24).toString("hex");
  return (await pool.query(`INSERT INTO statements(tenant_id,account_id,statement_number,period_start,period_end,due_at,opening_balance,new_charges,credits_and_payments,closing_balance,currency,status,snapshot,issued_at,payment_token,scheduled_charge_at) VALUES($1,$2,$3,$4,$5,($5::date+$6::int),$7,$8,$9,$10,$11,'issued',$12,now(),$13,$14) RETURNING *`,[user.tenant_id,accountId,statementNumber,input.periodStart,input.periodEnd,account.rows[0].payment_terms_days,openingBalance,charges,credits,Math.max(0,closing),currency,JSON.stringify(snapshot),token,input.scheduledChargeAt||null])).rows[0];
}

async function collectStatement(pool,square,config,statement,sourceId,idempotencyKey,actorId=null,paymentMethod="Card",requestedAmount,orderId){
  if(["paid","void"].includes(statement.status)||Number(statement.closing_balance)<=0)throw Object.assign(new Error("This statement has no outstanding balance."),{status:409});
  const tenantSquare=typeof square.forTenant==="function"?await square.forTenant(statement.tenant_id):square;
  return transaction(pool,async client=>{
    await client.query("SELECT id FROM statements WHERE id=$1 FOR UPDATE",[statement.id]);
    const duplicate=await client.query("SELECT * FROM payment_allocations WHERE tenant_id=$1 AND metadata->>'idempotencyKey'=$2",[statement.tenant_id,idempotencyKey]);
    const paid=Number((await client.query("SELECT COALESCE(SUM(amount),0)::bigint AS total FROM payment_allocations WHERE statement_id=$1 AND status='completed'",[statement.id])).rows[0].total),statementRemaining=Math.max(0,Number(statement.closing_balance)-paid);
    if(duplicate.rowCount)return {id:duplicate.rows[0].square_payment_id,status:"COMPLETED",appliedAmount:Number(duplicate.rows[0].amount),remainingBalance:statementRemaining};
    let maximum=statementRemaining,order=null;
    if(orderId){order=(await client.query(`SELECT o.*,GREATEST(0,o.total-COALESCE(SUM(pa.amount) FILTER (WHERE pa.status='completed'),0))::bigint AS balance_due FROM orders o LEFT JOIN payment_allocations pa ON pa.order_id=o.id WHERE o.id=$1 AND o.account_id=$2 AND o.payment_method='house_account' AND o.ordered_at::date BETWEEN $3 AND $4 GROUP BY o.id`,[orderId,statement.account_id,statement.period_start,statement.period_end])).rows[0];if(!order)throw Object.assign(new Error("That order is not an unpaid credit purchase on this statement."),{status:409});maximum=Math.min(maximum,Number(order.balance_due));}
    const amount=requestedAmount==null?maximum:Number(requestedAmount);
    if(!maximum)throw Object.assign(new Error("The selected balance is already paid."),{status:409});
    if(amount>maximum)throw Object.assign(new Error(`Payment cannot exceed the remaining balance of ${formatMoney(maximum,statement.currency)}.`),{status:400,code:"PAYMENT_EXCEEDS_BALANCE"});
    const payment=(await tenantSquare.createPayment({idempotency_key:idempotencyKey,source_id:sourceId,amount_money:{amount,currency:statement.currency},customer_id:statement.square_customer_id,location_id:config.squareLocationId,reference_id:order?.receipt_number||statement.statement_number,note:order?`Payment for order ${order.receipt_number||order.square_order_id}`:`Institutional account collection ${statement.statement_number}`,autocomplete:true})).payment;
    const remainingBalance=statementRemaining-amount;
    await client.query(`INSERT INTO payment_allocations(tenant_id,account_id,statement_id,order_id,square_payment_id,amount,currency,status,received_at,metadata) VALUES($1,$2,$3,$4,$5,$6,$7,'completed',now(),$8) ON CONFLICT(tenant_id,square_payment_id) DO NOTHING`,[statement.tenant_id,statement.account_id,statement.id,order?.id||null,payment.id,amount,statement.currency,JSON.stringify({idempotencyKey,paymentMethod,appliesTo:order?"order":"statement"})]);
    await postPayment(client,{tenantId:statement.tenant_id,accountId:statement.account_id,paymentId:payment.id,amount,currency:statement.currency,description:order?`Payment for order ${order.receipt_number||order.square_order_id}`:`Payment for ${statement.statement_number}`,actorId});
    await client.query("UPDATE statements SET status=$2,paid_at=CASE WHEN $2='paid' THEN now() ELSE NULL END,scheduled_charge_at=CASE WHEN $2='paid' THEN NULL ELSE scheduled_charge_at END WHERE id=$1",[statement.id,remainingBalance?"partially_paid":"paid"]);
    return {...payment,appliedAmount:amount,remainingBalance};
  });
}

async function audit(pool,user,request,action,targetType,targetId,before,after){ await pool.query(`INSERT INTO audit_log(tenant_id,actor_user_id,action,target_type,target_id,before_state,after_state,ip_address,user_agent) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,[user.tenant_id,user.id,action,targetType,targetId,before?JSON.stringify(before):null,after?JSON.stringify(after):null,request.ip,request.get("user-agent")]); }
function requireCron(request,config){const expected=config.cronSecret;if(!expected||request.get("authorization")!==`Bearer ${expected}`)throw Object.assign(new Error("Cron authorization required."),{status:401,code:"UNAUTHORIZED"});}
function smtpTransport(config){return nodemailer.createTransport({host:config.smtpHost,port:config.smtpPort,secure:config.smtpSecure,auth:{user:config.smtpUser,pass:config.smtpPassword}});}
async function sendEmail(config,{to,subject,text}){if(!(config.smtpHost&&config.smtpUser&&config.smtpPassword&&to))return false;try{await smtpTransport(config).sendMail({from:config.emailFrom,to,replyTo:config.emailReplyTo,subject,text});return true;}catch(error){console.error("Email delivery failed",error);return false;}}
async function notifyOwners(config,subject,text){return sendEmail(config,{to:config.ownerEmails,subject,text});}
function validSquareSignature(request,config){
  if(!config.squareWebhookSignatureKey||!config.squareWebhookNotificationUrl)return false;
  const supplied=request.get("x-square-hmacsha256-signature")||"";
  const expected=createHmac("sha256",config.squareWebhookSignatureKey).update(config.squareWebhookNotificationUrl).update(request.rawBody||Buffer.from(JSON.stringify(request.body))).digest("base64");
  const left=Buffer.from(supplied),right=Buffer.from(expected);
  return left.length===right.length&&timingSafeEqual(left,right);
}
function statementEmail(statement,siteUrl){const amount=new Intl.NumberFormat("en-CA",{style:"currency",currency:statement.currency}).format(Number(statement.closing_balance)/100),label=statement.notification_type==='overdue'?"is overdue":statement.notification_type==='due_soon'?"is due soon":"is ready",paymentUrl=`${siteUrl}/account/?statement=${encodeURIComponent(statement.payment_token)}`;return `<div style="font-family:Arial,sans-serif;color:#17394a;max-width:560px"><h1 style="font-size:24px">Your Amazing Donuts statement ${label}</h1><p>${statement.organization_name}</p><p><strong>${amount}</strong> is due ${String(statement.due_at).slice(0,10)}.</p><p>HST is already included in the underlying purchases.</p><p><a href="${paymentUrl}" style="display:inline-block;background:#d5008f;color:white;padding:12px 18px;text-decoration:none">View statement and pay</a></p></div>`;}
async function collectDueStatements(pool,square,config){
  const due=await pool.query(`SELECT s.*,a.organization_name,a.billing_email,a.square_customer_id,ac.square_card_id FROM statements s JOIN accounts a ON a.id=s.account_id JOIN account_cards ac ON ac.account_id=a.id AND ac.status='active' WHERE s.status IN ('issued','partially_paid','overdue') AND s.due_at<=CURRENT_DATE AND s.closing_balance>0 AND NOT EXISTS(SELECT 1 FROM payment_allocations pa WHERE pa.statement_id=s.id AND pa.status='completed') ORDER BY s.due_at LIMIT 25`),result={paid:0,failed:0};
  for(const statement of due.rows){try{const tenantSquare=typeof square.forTenant==="function"?await square.forTenant(statement.tenant_id):square,payment=(await tenantSquare.createPayment({idempotency_key:statement.id,source_id:statement.square_card_id,amount_money:{amount:Number(statement.closing_balance),currency:statement.currency},customer_id:statement.square_customer_id,location_id:config.squareLocationId,reference_id:statement.statement_number,note:`Automatic institutional account settlement ${statement.statement_number}`,autocomplete:true})).payment;await transaction(pool,async client=>{await client.query(`INSERT INTO payment_allocations(tenant_id,account_id,statement_id,square_payment_id,amount,currency,status,received_at,metadata) VALUES($1,$2,$3,$4,$5,$6,'completed',now(),$7) ON CONFLICT(tenant_id,square_payment_id) DO NOTHING`,[statement.tenant_id,statement.account_id,statement.id,payment.id,Number(statement.closing_balance),statement.currency,JSON.stringify({automatic:true,paymentMethod:"Saved card (automatic)"})]);await postPayment(client,{tenantId:statement.tenant_id,accountId:statement.account_id,paymentId:payment.id,amount:Number(statement.closing_balance),currency:statement.currency,description:`Automatic payment for ${statement.statement_number}`});await client.query("UPDATE statements SET status='paid',paid_at=now() WHERE id=$1",[statement.id]);});result.paid++;await Promise.all([sendEmail(config,{to:statement.billing_email,subject:`Payment received for ${statement.statement_number}`,text:`Your saved card was charged ${formatMoney(statement.closing_balance,statement.currency)}. Statement ${statement.statement_number} is paid.`}),notifyOwners(config,"Automatic statement payment received",`${statement.organization_name}\n${statement.statement_number}\n${formatMoney(statement.closing_balance,statement.currency)}`)]);}catch(error){result.failed++;await Promise.all([sendEmail(config,{to:statement.billing_email,subject:`Payment needed for ${statement.statement_number}`,text:`We could not charge the saved card for ${formatMoney(statement.closing_balance,statement.currency)}. Please sign in to update payment or pay the statement: ${config.siteUrl}/account/`}),notifyOwners(config,"Automatic statement payment failed",`${statement.organization_name}\n${statement.statement_number}\n${error.message}`)]);}}
  return result;
}
const formatMoney=(amount,currency="CAD")=>new Intl.NumberFormat("en-CA",{style:"currency",currency}).format(Number(amount)/100);
const datePlusDays=days=>{const date=new Date();date.setUTCDate(date.getUTCDate()+Number(days||0));return date.toISOString().slice(0,10);};
async function handleSquareNotification(pool,square,config,tenantId,event){
  const tenantSquare=typeof square.forTenant==="function"?await square.forTenant(tenantId):square;
  if(event.type?.startsWith("payment.")){const paymentId=event.data?.object?.payment?.id;if(!paymentId)return;const payment=(await tenantSquare.retrievePayment(paymentId)).payment;if(payment.status!=="COMPLETED"||payment.source_type==="EXTERNAL"||!payment.order_id)return;const found=await pool.query(`SELECT so.*,u.email FROM storefront_orders so JOIN users u ON u.id=so.user_id WHERE so.tenant_id=$1 AND so.square_order_id=$2 AND so.payment_method='house_account' LIMIT 1`,[tenantId,payment.order_id]);if(!found.rowCount)return;return;}
  if(event.type?.startsWith("invoice.")){const eventInvoice=event.data?.object?.invoice,invoiceId=eventInvoice?.id||event.data?.id;if(!invoiceId)return;const invoice=eventInvoice||((await tenantSquare.retrieveInvoice(invoiceId)).invoice),status=String(invoice.status||"UNPAID").toLowerCase(),found=await pool.query(`UPDATE storefront_orders SET status=$3 WHERE tenant_id=$1 AND square_invoice_id=$2 RETURNING *`,[tenantId,invoiceId,status]);if(found.rowCount&&["failed","canceled"].includes(status)){const customer=await pool.query("SELECT email FROM users WHERE id=$1",[found.rows[0].user_id]);await Promise.all([sendEmail(config,{to:customer.rows[0]?.email,subject:`Amazing Donuts invoice ${status}`,text:`The Square invoice for order ${found.rows[0].square_order_id} is ${status}. Please contact the bakery or use Square's invoice payment link.`}),notifyOwners(config,`Square invoice ${status}`,`${found.rows[0].square_order_id}\n${invoiceId}`)]);}return;}
  if(event.type?.startsWith("refund.")){const refundId=event.data?.object?.refund?.id;if(!refundId)return;const refund=(await tenantSquare.retrieveRefund(refundId)).refund;if(refund.status!=="COMPLETED")return;const found=await pool.query(`SELECT so.*,u.email FROM storefront_orders so JOIN users u ON u.id=so.user_id WHERE so.tenant_id=$1 AND so.square_payment_id=$2 LIMIT 1`,[tenantId,refund.payment_id]);if(!found.rowCount)return;await pool.query("UPDATE storefront_orders SET status='refunded' WHERE id=$1",[found.rows[0].id]);await Promise.all([sendEmail(config,{to:found.rows[0].email,subject:"Your Amazing Donuts refund was completed",text:`A refund of ${formatMoney(refund.amount_money?.amount,refund.amount_money?.currency)} was completed for order ${found.rows[0].square_order_id}.`}),notifyOwners(config,"Website order refunded",`${found.rows[0].square_order_id}\n${formatMoney(refund.amount_money?.amount,refund.amount_money?.currency)}`)]);return;}
  if(event.type?.includes("fulfillment")){const orderId=event.data?.object?.order_fulfillment_updated?.order_id||event.data?.object?.order?.id||event.data?.id;if(!orderId)return;const order=(await tenantSquare.retrieveOrder(orderId)).order,state=order.fulfillments?.[0]?.state||"PROPOSED",status={COMPLETED:"completed",CANCELED:"cancelled",FAILED:"cancelled"}[state]||"posted";const found=await pool.query(`UPDATE storefront_orders SET status=$3 WHERE tenant_id=$1 AND square_order_id=$2 RETURNING *`,[tenantId,orderId,status]);await pool.query("UPDATE orders SET status=$3 WHERE tenant_id=$1 AND square_order_id=$2",[tenantId,orderId,status==="completed"?"posted":status]);if(found.rowCount){const customer=await pool.query("SELECT email FROM users WHERE id=$1",[found.rows[0].user_id]),label=state==="PREPARED"?"ready":state.toLowerCase();await sendEmail(config,{to:customer.rows[0]?.email,subject:`Your Amazing Donuts order is ${label}`,text:`Order ${orderId} is ${label}. View your orders: ${config.siteUrl}/account/`});}}
}

export const normalizeNorthAmericanPhone=value=>{const digits=String(value||"").replace(/\D/g,"").replace(/^1(?=\d{10}$)/,"");return digits?`+1${digits}`:"";};
const isValidNorthAmericanPhone=value=>/^[2-9]\d{2}[2-9]\d{6}$/.test(normalizeNorthAmericanPhone(value).slice(2));
const normalizeName=value=>String(value||"").toLowerCase().replace(/&/g,"and").replace(/[^a-z0-9]+/g," ").trim();
const printProductNames=new Set(["twelve custom printed donuts","twelve custom printed cupcakes"]);
const validatePrintedItems=input=>{for(const item of input.items){if(!printProductNames.has(normalizeName(item.name)))continue;if(item.quantity<4)throw Object.assign(new Error("Custom-printed items have a minimum purchase of four dozen units."),{status:409,code:"PRINT_MINIMUM_REQUIRED"});if(new Date(input.fulfillment.scheduledAt).getTime()<Date.now()+7*86400000)throw Object.assign(new Error("Custom-printed items require a minimum of one week's notice."),{status:409,code:"PRINT_LEAD_TIME_REQUIRED"});const custom=input.customizations?.find(entry=>normalizeName(entry.productName)===normalizeName(item.name));if(custom?.kind!=="print"||custom.artworks.some(art=>art.count>4)||custom.artworks.reduce((sum,art)=>sum+art.count,0)!==item.quantity)throw Object.assign(new Error("Assign one print file for each group of up to four dozen units."),{status:409,code:"PRINT_ARTWORK_REQUIRED"});}};
async function catalogObjects(square){let cursor,objects=[];do{const page=await square.request("/v2/catalog/list",{query:{types:"ITEM,TAX",...(cursor?{cursor}:{})}});objects.push(...(page.objects||[]));cursor=page.cursor;}while(cursor);return objects;}
async function buildSquareOrder(square,locationId,input,user){
  if(!locationId)throw Object.assign(new Error("The Square checkout location is not configured."),{status:503});
  const objects=await catalogObjects(square),items=objects.filter(x=>x.type==="ITEM"),taxes=objects.filter(x=>x.type==="TAX"&&x.is_deleted!==true);
  const lineItems=input.items.map(line=>{
    const wanted=normalizeName(line.name),item=items.find(x=>normalizeName(x.item_data?.name)===wanted),variation=item?.item_data?.variations?.find(v=>v.item_variation_data?.price_money?.amount!=null&&!v.is_deleted);
    if(!variation)throw Object.assign(new Error(`${line.name} is not currently available in the Square catalog.`),{status:409,code:"CATALOG_ITEM_UNAVAILABLE"});
    const custom=input.customizations?.find(entry=>normalizeName(entry.productName)===wanted),note=custom?.kind==="glyph"?`CUSTOM CAKE: ${custom.glyph}`:custom?.kind==="print"?`CUSTOM PRINT: ${custom.icingFlavor} icing${custom.sprinkleColours?`, ${custom.sprinkleColours} sprinkles`:""}. ${custom.artworks.map((art,index)=>`Design ${index+1} x ${art.count} dozen units`).join(", ")}. Artwork files are in the Amazing Donuts order portal.`:undefined;
    return {catalog_object_id:variation.id,quantity:String(line.quantity),...(note?{note}:{})};
  });
  const recipient={display_name:input.fulfillment.recipient.displayName,email_address:input.fulfillment.recipient.email,phone_number:normalizeNorthAmericanPhone(input.fulfillment.recipient.phone)};
  if(input.fulfillment.address)recipient.address={address_line_1:input.fulfillment.address.addressLine1,address_line_2:input.fulfillment.address.addressLine2||undefined,locality:input.fulfillment.address.locality,administrative_district_level_1:input.fulfillment.address.administrativeDistrictLevel1,postal_code:input.fulfillment.address.postalCode,country:input.fulfillment.address.country};
  const fulfillment=input.fulfillment.type==="pickup"?{type:"PICKUP",state:"PROPOSED",pickup_details:{schedule_type:"SCHEDULED",pickup_at:input.fulfillment.scheduledAt,recipient}}:{type:"DELIVERY",state:"PROPOSED",delivery_details:{schedule_type:"SCHEDULED",deliver_at:input.fulfillment.scheduledAt,recipient,...(input.fulfillment.deliveryInstructions?{delivery_instructions:input.fulfillment.deliveryInstructions}:{}),...(input.fulfillment.noContact?{no_contact_delivery:true}:{})}};
  return {location_id:locationId,line_items:lineItems,fulfillments:[fulfillment],taxes:taxes.map((tax,index)=>({uid:`catalog-tax-${index}`,catalog_object_id:tax.id,scope:"ORDER"})),pricing_options:{auto_apply_taxes:true,auto_apply_discounts:true},source:{name:"Amazing Donuts Website"},reference_id:`web-${user.id.slice(0,8)}-${Date.now()}`};
}
async function prepareSquareOrder(square,config,input,user){
  validateFulfillmentSchedule(input.fulfillment);
  validateDelivery(input.fulfillment,config.delivery);
  validatePrintedItems(input);
  const orderDraft=await buildSquareOrder(square,config.squareLocationId,input,user);
  const initial=(await square.request("/v2/orders/calculate",{method:"POST",body:{order:orderDraft}})).order;
  const fee=deliveryFee(merchandiseSubtotal(initial),input.fulfillment,config.delivery);
  if(fee)orderDraft.service_charges=deliveryServiceCharge(fee);
  const calculated=fee?(await square.request("/v2/orders/calculate",{method:"POST",body:{order:orderDraft}})).order:initial;
  return {orderDraft,calculated};
}
const publicDelivery=(order,input,policy)=>input.fulfillment.type==="delivery"?{provider:policy.provider,status:"AWAITING_MANUAL_DISPATCH",fee:Number(order.total_service_charge_money?.amount||0),free:Number(order.total_service_charge_money?.amount||0)===0}:null;
const publicOrder=order=>({id:order.id,total:Number(order.total_money?.amount||0),subtotal:Number(order.total_money?.amount||0)-Number(order.total_tax_money?.amount||0),tax:Number(order.total_tax_money?.amount||0),currency:order.total_money?.currency||"CAD",state:order.state,lineItems:(order.line_items||[]).map(x=>({name:x.name,quantity:x.quantity,total:Number(x.total_money?.amount||0)})),fulfillments:order.fulfillments||[]});
